import csv
with open('outputs/t01_selected_indicators.csv', 'r') as f:
    reader = csv.DictReader(f)
    themes = {}
    for row in reader:
        theme = row['theme']
        themes[theme] = themes.get(theme, 0) + 1
    for theme, count in sorted(themes.items()):
        print(f'{theme}: {count}')
    print(f'Total rows: {sum(themes.values())}')
